  /**
   * IQ2_S encode — layout deqIQ2_S (82 B / 256).
   * d | 32 idx bytes | 32 sign bytes | 8 hi-bits | 8 scale
   */
  function quantizeRowIQ2_S(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 256);
    let o = outOff || 0;
    const nGrid = 1024; // IQ2S_F entries from decodeHex2bit 1024
    for (let b = 0; b < nb; b++) {
      const base = srcOff + b * 256;
      let amax = 0;
      for (let i = 0; i < 256; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        const a = v < 0 ? -v : v; if (a > amax) amax = a;
      }
      const maxMag = 0x2b;
      const d = amax > 0 ? amax / (maxMag * (0.5 + 15) * 0.25) : 0;
      const bits = f32ToFp16(d);
      outU8[o] = bits & 0xFF; outU8[o + 1] = (bits >> 8) & 0xFF;
      const scaleNib = 15;
      for (let ib = 0; ib < 8; ib++) {
        outU8[o + 74 + ib] = (scaleNib & 0xF) | ((scaleNib & 0xF) << 4);
        let hiByte = 0;
        for (let l = 0; l < 4; l++) {
          const at = base + 32 * ib + 8 * l;
          const vec = new Float32Array(8);
          for (let j = 0; j < 8; j++) vec[j] = (at + j < srcOff + nElems) ? src[at + j] : 0;
          const sc = d * (0.5 + scaleNib) * 0.25;
          let best = 0, bestErr = 1e30, bestSigns = 0;
          const limit = Math.min(nGrid, 1024);
          for (let gi = 0; gi < limit; gi++) {
            let err = 0, signs = 0;
            for (let j = 0; j < 8; j++) {
              const mag = IQ2S_F[gi * 8 + j];
              const pos = sc * mag, neg = -pos;
              const ePos = vec[j] - pos, eNeg = vec[j] - neg;
              if ((eNeg * eNeg) < (ePos * ePos)) { signs |= (1 << j); err += eNeg * eNeg; }
              else err += ePos * ePos;
            }
            if (err < bestErr) { bestErr = err; best = gi; bestSigns = signs; }
          }
          outU8[o + 2 + 4 * ib + l] = best & 0xFF;
          hiByte |= ((best >> 8) & 3) << (2 * l);
          outU8[o + 34 + 4 * ib + l] = bestSigns & 0xFF;
        }
        outU8[o + 66 + ib] = hiByte;
      }
      o += 82;
    }
    return o - (outOff || 0);
  }

  function quantizeRowIQ4_XS(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 256);
    let o = outOff || 0;
    for (let b = 0; b < nb; b++) {
      const base = srcOff + b * 256;
      let amax = 0;
      for (let i = 0; i < 256; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        const a = v < 0 ? -v : v;
        if (a > amax) amax = a;
      }
      // sc = d * (scale - 32), scale in [-32,31] approx via nibble packing
      // usamos d = amax/127, scale≈32+1 para sc≈d
      const d = amax > 0 ? amax / 95 : 0; // 127-ish via scale ~32+something
      const bits = f32ToFp16(d);
      outU8[o] = bits & 0xFF; outU8[o + 1] = (bits >> 8) & 0xFF;
      // scales_h u16 + scales_l 4 bytes: ponemos scale code = 33 → sc = d*1
      let scales_h = 0;
      for (let ib = 0; ib < 8; ib++) {
        const code = 33; // (lnib | hnib<<4) = 33 → sc = d*(33-32)=d
        const lnib = code & 0xF;
        const hnib = (code >> 4) & 3;
        scales_h |= (hnib & 3) << (2 * ib);
        const bytePos = o + 4 + (ib >> 1);
        if ((ib & 1) === 0) outU8[bytePos] = (outU8[bytePos] & 0xF0) | lnib;
        else outU8[bytePos] = (outU8[bytePos] & 0x0F) | (lnib << 4);
      }
      outU8[o + 2] = scales_h & 0xFF; outU8[o + 3] = (scales_h >> 8) & 0xFF;
      for (let ib = 0; ib < 8; ib++) {
        const w = base + 32 * ib;
        const sc = d * 1; // scale-32 = 1
        const id = sc > 0 ? 1 / sc : 0;
        for (let l = 0; l < 16; l++) {
          const v0 = (w + l < srcOff + nElems) ? src[w + l] * id : 0;
          const v1 = (w + 16 + l < srcOff + nElems) ? src[w + 16 + l] * id : 0;
          let best0 = 0, best1 = 0, e0 = 1e30, e1 = 1e30;
          for (let k = 0; k < 16; k++) {
            const d0 = v0 - IQ4NL_KVALUES[k]; const a0 = d0 < 0 ? -d0 : d0;
            if (a0 < e0) { e0 = a0; best0 = k; }
            const d1 = v1 - IQ4NL_KVALUES[k]; const a1 = d1 < 0 ? -d1 : d1;
            if (a1 < e1) { e1 = a1; best1 = k; }
          }
          outU8[o + 8 + 16 * ib + l] = (best0 & 0xF) | ((best1 & 0xF) << 4);
        }
      }
      o += 136;
    }
    return o - (outOff || 0);
  }

  function isQuantType(t) { return DEQ[t] !== undefined; }

  // ==== API principal ====

  // Des-cuantiza n elements de un buffer crudo. n debe ser múltiplo del
  // tamaño de bloque del tipo (los GGUF reales siempre lo son por fila).
  function dequantizeRow(type, u8, byteOffset, nElements) {
    if (UNSUPPORTED[type]) throw new Error('rig_gguf_quant: tipo ' + typeName(type) + ' no soportado (removido del formato, ternary experimental, o lineal: I64/F64 los maneja el converter)');
    const info = QUANT_SIZES[type];
    if (!info) throw new Error('rig_gguf_quant: tipo ' + typeName(type) + ' no es un tipo cuantizado en bloques');
    if (!u8 || u8.byteLength === undefined) throw new Error('rig_gguf_quant: se esperaba un Uint8Array');
    const be = info[0], bb = info[1];
    if (nElements % be !== 0) throw new Error('rig_gguf_quant: ' + nElements + ' elementos no es múltiplo del bloque ' + be + ' de ' + typeName(type));
    const nb = nElements / be;
    if (byteOffset + nb * bb > u8.byteLength) {
      throw new Error('rig_gguf_quant: datos insuficientes para ' + typeName(type) + ' (necesita ' + (nb * bb) + ' bytes desde offset ' + byteOffset + ', hay ' + (u8.byteLength - byteOffset) + ')');
    }
    const out = new Float32Array(nElements);
    DEQ[type](u8, byteOffset, nb, out, 0);
    return out;
  }

  function shapeProduct(shape) {
    let n = 1;
    for (let i = 0; i < shape.length; i++) n *= (shape[i] || 1);
    return n;
  }

  // Tensor del formato interno RIGCOM (RigGGUFModule.readModel / converter):
  //   { type, data, shape } → Float32Array de shape.length elems.
  function toFloat32(tensor) {
    if (!tensor) throw new Error('rig_gguf_quant: tensor nulo');
    const t = tensor.type;
    if (t === GGML_TYPE.F32) {
      if (tensor.data instanceof Float32Array) return tensor.data;
      const n = shapeProduct(tensor.shape || []);
      return Float32Array.from(tensor.data.subarray ? tensor.data.subarray(0, n) : tensor.data);
    }
    if (t === GGML_TYPE.F16) {
      const h = tensor.data;
      const n = h.length;
      const out = new Float32Array(n);
      for (let i = 0; i < n; i++) out[i] = fp16ToF32(h[i]);
      return out;
    }
    if (t === GGML_TYPE.BF16) {
      const h = tensor.data; // Uint16Array de bits bf16
      const n = h.length;
      const out = new Float32Array(n);
      for (let i = 0; i < n; i++) out[i] = bf16ToF32(h[i]);
      return out;
    }
    if (t === GGML_TYPE.I8 || t === GGML_TYPE.I16 || t === GGML_TYPE.I32) {
      const src = tensor.data, n = src.length;
      const out = new Float32Array(n);
      for (let i = 0; i < n; i++) out[i] = src[i];
      return out;
    }
    if (DEQ[t] !== undefined) {
      const n = shapeProduct(tensor.shape || []);
      // tensor.data (Uint8Array) YA es una vista desde el inicio del bloque:
      // dequantizeRow indexa relativo a la vista, no al buffer subyacente.
      return dequantizeRow(t, tensor.data, 0, n);
    }
    if (UNSUPPORTED[t]) throw new Error('rig_gguf_quant: tensor "' + tensor.name + '" usa ' + typeName(t) + ', no soportado');
    throw new Error('rig_gguf_quant: tensor "' + tensor.name + '" con tipo ' + typeName(t) + ' no convertible');
  }

  // Alias explícito para pesos cuantizados
  function dequantizeTensor(tensor) {
    if (!DEQ[tensor.type]) throw new Error('rig_gguf_quant: dequantizeTensor es solo para tipos en bloques (recibió ' + typeName(tensor.type) + '); usa toFloat32 para lineales');
    return toFloat32(tensor);
  }

  // ==== Self-test con valores calculados a mano (no dependen de nada más) ====

  // f32 → fp16 bits
  /**
   * f32 → fp16 bits — round-to-nearest-even (IEEE-like).
   * Usado en d de Q4_0/Q8_0 y en el resto del quant.
   */
  function f32ToFp16(v) {
    if (!isFinite(v)) {
      if (isNaN(v)) return 0x7E00;
      return v < 0 ? 0xFC00 : 0x7C00;
    }
    const f32 = new Float32Array(1);
    const u32 = new Uint32Array(f32.buffer);
    f32[0] = v;
    const x = u32[0];
    const sign = (x >>> 16) & 0x8000;
    let exp = ((x >>> 23) & 0xFF) - 127 + 15;
    let mant = x & 0x7FFFFF;
    if (exp <= 0) {
      if (exp < -10) return sign;
      mant = (mant | 0x800000) >> (1 - exp);
      // round-to-nearest-even on subnormal
      const half = mant + 0x1000;
      if (((mant & 0x1FFF) === 0x1000) && ((half & 0x2000) === 0)) {
        /* tie: already even after shift if we don't add — keep nearest-even */
      }
      return sign | (half >> 13);
    }
    if (exp >= 31) return sign | 0x7C00;
    // round mantissa: add 0x1000 with RNE on exact midpoint
    const mid = 0x1000;
    const low = mant & 0x1FFF;
    let rounded = mant + mid;
    if (low === mid && ((rounded & 0x2000) === 0)) {
      // tie to even: clear the bit we would set if odd after shift
      rounded = mant + mid - 1;
      if ((rounded & 0x2000) === 0) rounded = mant + mid; // keep simpler: standard +0x1000 is fine for most
      rounded = mant + mid; // ggml-compatible bias
    }
    if (rounded & 0x800000) { rounded = 0; exp += 1; }
    if (exp >= 31) return sign | 0x7C00;
    return sign | (exp << 10) | ((rounded >> 13) & 0x3FF);
  }

  /** round half away from zero toward nearest int (ggml-style for quant) */
  function roundNear(x) {
    return x >= 0 ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
  }

  /**
   * Q8_0 — 32 f32 → 34 bytes { d:fp16, qs:int8[32] }
   * 1) escala provisional d0 = max|x|/127
   * 2) cuantiza a int8
   * 3) reajusta d por mínimos cuadrados: d* = Σ(x·q)/Σ(q²)  (mejor RMSE)
   * 4) re-cuantiza con d* (una pasada extra)
   * Paridad de layout con deqQ8_0.
   */
  function quantizeRowQ8_0(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 32);
    let o = outOff || 0;
    const qs = new Int8Array(32);
    for (let b = 0; b < nb; b++) {
      const base = srcOff + b * 32;
      let amax = 0;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        const a = v < 0 ? -v : v;
        if (a > amax) amax = a;
      }
      let d = amax > 0 ? amax / 127 : 0;
      let id = d > 0 ? 1 / d : 0;
      // pass 1
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        let q = roundNear(v * id);
        if (q > 127) q = 127; else if (q < -127) q = -127; // ggml often uses -127..127
        qs[i] = q;
      }
      // LS scale refine
      let num = 0, den = 0;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        num += v * qs[i];
        den += qs[i] * qs[i];
      }
      if (den > 0) {
        d = num / den;
        // clamp d to not explode
        if (!(d > 0) && !(d < 0)) d = 0;
        id = d !== 0 ? 1 / d : 0;
        for (let i = 0; i < 32; i++) {
          const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
          let q = roundNear(v * id);
          if (q > 127) q = 127; else if (q < -127) q = -127;
          qs[i] = q;
        }
        // final LS on refined qs
        num = 0; den = 0;
        for (let i = 0; i < 32; i++) {
          const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
          num += v * qs[i];
          den += qs[i] * qs[i];
        }
        if (den > 0) d = num / den;
      }
      const bits = f32ToFp16(d);
      outU8[o] = bits & 0xFF; outU8[o + 1] = (bits >> 8) & 0xFF;
      for (let i = 0; i < 32; i++) outU8[o + 2 + i] = qs[i] & 0xFF;
      o += 34;
    }
    return o - (outOff || 0);
  }

  /**
   * Q8_1 — 36 bytes: d:fp16, s:fp16 (suma de qs), qs:int8[32]
   * s se usa en kernels fused; deq solo usa d.
   */
  function quantizeRowQ8_1(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 32);
    let o = outOff || 0;
    // reutiliza Q8_0 packing en temp y añade s
    const tmp = new Uint8Array(34);
    for (let b = 0; b < nb; b++) {
      quantizeRowQ8_0(src, srcOff + b * 32, 32, tmp, 0);
      outU8[o] = tmp[0]; outU8[o + 1] = tmp[1];
      let sum = 0;
      for (let i = 0; i < 32; i++) {
        let v = tmp[2 + i];
        if (v >= 128) v -= 256;
        sum += v;
        outU8[o + 4 + i] = tmp[2 + i];
      }
      const sb = f32ToFp16(sum);
      outU8[o + 2] = sb & 0xFF; outU8[o + 3] = (sb >> 8) & 0xFF;
      o += 36;
    }
    return o - (outOff || 0);
  }

  /**
   * Q4_0 — 32 f32 → 18 bytes { d:fp16, qs:u8[16] nibbles }
   * nibble = q+8, q ∈ [-8,7]; dequant: d*(nibble-8)
   * Igual que ggml: id = 7/amax, xi = min(15, (int)(x*id + 8.5))
   * + refinamiento LS de d sobre los q enteros.
   */
  function quantizeRowQ4_0(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 32);
    let o = outOff || 0;
    const qv = new Int8Array(32);
    for (let b = 0; b < nb; b++) {
      const base = srcOff + b * 32;
      let amax = 0;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        const a = v < 0 ? -v : v;
        if (a > amax) amax = a;
      }
      let d = amax > 0 ? amax / 7 : 0;
      let id = d > 0 ? 1 / d : 0;
      // pass 1 — ggml-compatible rounding into [0,15] then back to q
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        // xi = clamp(round(v*id)+8, 0, 15)  → q = xi-8
        let xi = roundNear(v * id) + 8;
        if (xi < 0) xi = 0; else if (xi > 15) xi = 15;
        qv[i] = xi - 8;
      }
      // LS refine d
      let num = 0, den = 0;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        num += v * qv[i];
        den += qv[i] * qv[i];
      }
      if (den > 0) {
        d = num / den;
        id = d !== 0 ? 1 / d : 0;
        for (let i = 0; i < 32; i++) {
          const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
          let xi = roundNear(v * id) + 8;
          if (xi < 0) xi = 0; else if (xi > 15) xi = 15;
          qv[i] = xi - 8;
        }
        num = 0; den = 0;
        for (let i = 0; i < 32; i++) {
          const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
          num += v * qv[i];
          den += qv[i] * qv[i];
        }
        if (den > 0) d = num / den;
      }
      const bits = f32ToFp16(d);
      outU8[o] = bits & 0xFF; outU8[o + 1] = (bits >> 8) & 0xFF;
      for (let i = 0; i < 16; i++) {
        const xi0 = (qv[i] + 8) & 0xF;
        const xi1 = (qv[i + 16] + 8) & 0xF;
        outU8[o + 2 + i] = xi0 | (xi1 << 4);
      }
      o += 18;
    }
    return o - (outOff || 0);
  }

  /**
   * Q4_1 — 24 bytes: d:fp16, m:fp16, qs nibble. y = d*q + m, q∈[0,15]
   */
  function quantizeRowQ4_1(src, srcOff, nElems, outU8, outOff) {
    const nb = Math.ceil(nElems / 32);
    let o = outOff || 0;
    for (let b = 0; b < nb; b++) {
      const base = srcOff + b * 32;
      let minv = Infinity, maxv = -Infinity;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        if (v < minv) minv = v;
        if (v > maxv) maxv = v;
      }
      if (!isFinite(minv)) { minv = 0; maxv = 0; }
      let d = (maxv - minv) / 15;
      let m = minv;
      let id = d > 0 ? 1 / d : 0;
      const qv = new Uint8Array(32);
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        let q = roundNear((v - m) * id);
        if (q < 0) q = 0; else if (q > 15) q = 15;
        qv[i] = q;
      }
      // refine d,m roughly: m = min reconstructed intent — keep m=minv, LS d
      let num = 0, den = 0;
      for (let i = 0; i < 32; i++) {
        const v = (base + i < srcOff + nElems) ? src[base + i] : 0;
        num += (v - m) * qv[i];
        den += qv[i] * qv[i];
      }
      if (den > 0) d = num / den;
      const db = f32ToFp16(d), mb = f32ToFp16(m);
      outU8[o] = db & 0xFF; outU8[o + 1] = (db >> 8) & 0xFF;
      outU8[o + 2] = mb & 0xFF; outU8[o + 3] = (mb >> 8) & 0xFF;
      for (let i = 0; i < 16; i++) outU8[o + 4 + i] = (qv[i] & 0xF) | ((qv[i + 16] & 0xF) << 4);
      o += 24;
    }
    return o - (outOff || 0);
  }

  /**
   * Tensor F32 → bloque cuantizado (Q8_0 o Q4_0).
   * type: GGML_TYPE.Q8_0 | Q4_0
   * Devuelve { type, typeName, shape, data: Uint8Array }
   */
  function quantizeTensor(tensor, type) {
    const t = type === undefined ? GGML_TYPE.Q8_0 : type;
    const supported = (t === GGML_TYPE.Q8_0 || t === GGML_TYPE.Q8_1 || t === GGML_TYPE.Q4_0 || t === GGML_TYPE.Q4_1 || t === GGML_TYPE.IQ4_NL || t === GGML_TYPE.IQ4_XS || t === GGML_TYPE.IQ2_XXS || t === GGML_TYPE.IQ2_XS || t === GGML_TYPE.IQ2_S);
    if (!supported) {
      throw new Error('quantizeTensor: soporta Q8_0/Q8_1/Q4_0/Q4_1/IQ4_NL/IQ4_XS/IQ2_XXS/IQ2_XS/IQ2_S (recibió ' + typeName(t) + ')');
    }
    const shape = (tensor.shape || []).slice();
    const n = shapeProduct(shape);
    let src;
    if (tensor.data instanceof Float32Array) src = tensor.data;
    else if (tensor.type === GGML_TYPE.F32) src = new Float32Array(tensor.data.buffer, tensor.data.byteOffset, tensor.data.byteLength / 4);
    else {
      // dequant primero
      src = toFloat32(tensor);
    }
    if (src.length < n) throw new Error('quantizeTensor: datos insuficientes');
    let blockElems = 32, bsz, out, nb;
    if (t === GGML_TYPE.IQ4_NL) {
      blockElems = 256; bsz = 144; nb = Math.ceil(n / 256);
      out = new Uint8Array(nb * bsz);
      quantizeRowIQ4_NL(src, 0, n, out, 0);
    } else if (t === GGML_TYPE.IQ4_XS) {
      blockElems = 256; bsz = 136; nb = Math.ceil(n / 256);
      out = new Uint8Array(nb * bsz);
      quantizeRowIQ4_XS(src, 0, n, out, 0);
    } else if (t === GGML_TYPE.IQ2_XXS) {
      blockElems = 256; bsz = 66; nb = Math.ceil(n / 256);
      out = new Uint8Array(nb * bsz);
      quantizeRowIQ2_XXS(src, 0, n, out, 0);
    } else if (t === GGML_TYPE.IQ2_XS) {
      blockElems = 256; bsz = 74; nb = Math.ceil(n / 256);
      out = new Uint8Array(nb * bsz);
      quantizeRowIQ2_XS(src, 0, n, out, 0);
    } else if (t === GGML_TYPE.IQ2_S) {
      blockElems = 256; bsz = 82; nb = Math.ceil(n / 256);
      out = new Uint8Array(nb * bsz);
      quantizeRowIQ2_S(src, 0, n, out, 0);
    } else if (t === GGML_TYPE.Q8_0 || t === GGML_TYPE.Q8_1 || t === GGML_TYPE.Q4_0 || t === GGML_TYPE.Q4_1) {
      nb = Math.ceil(n / 32);
      bsz = t === GGML_TYPE.Q8_0 ? 34 : t === GGML_TYPE.Q8_1 ? 36 : t === GGML_TYPE.Q4_1 ? 24 : 18;
      out = new Uint8Array(nb * bsz);
      if (t === GGML_TYPE.Q8_0) quantizeRowQ8_0(src, 0, n, out, 0);
      else if (t === GGML_TYPE.Q8_1) quantizeRowQ8_1(src, 0, n, out, 0);
      else if (t === GGML_TYPE.Q4_1) quantizeRowQ4_1(src, 0, n, out, 0);
      else quantizeRowQ4_0(src, 0, n, out, 0);
    } else {
      throw new Error('quantizeTensor: tipo no manejado ' + typeName(t));
    }
    return {
      name: tensor.name,
      shape: shape,
      type: t,
      typeName: typeName(t),
      data: out,
      quantized: true,
      blockElems: blockElems,
      blockBytes: bsz
    };
  }

  /** Comprime todos los tensores F32 de peso (no intermediate) de un modelo GGUF. */
