      const ty = n.var_decl.decl_type
                 ? type_to_irtype(n.var_decl.decl_type.kind)
                 : IRTY.I64;
      const slot = ir_emit_alloca(lc.fn, ty, 1);
      /* [DIVERGE-C por orden del arquitecto] registrar el local en la
         tabla del lowering para que IDENT_EXPR pueda leerlo */
