function cpp_native_header(src, src_path) {
  /* header C desde el parser C++ nativo: prototipos de las funciones */
  const mod = cpp_native_compile(src, src_path, null);
  if (!mod) return null;
  const guard = "RIGCOM_CPP_" + String(src_path).replace(/[^A-Za-z0-9]/g, "_").toUpperCase();
  const out = [];
  out.push("/* Auto-generado por RIGCOMPILER_JS — frontend C++ nativo */\n");
  out.push("#ifndef " + guard + "\n#define " + guard + "\n\n");
  out.push('#include "rigdeps/stdint.h"\n\n');
  for (let i = 0; i < mod.n_funcs; i++) {
    const f = mod.funcs[i]; if (!f) continue;
    const ps = [];
    for (let k = 0; k < f.n_params; k++) ps.push("int64_t " + (f.params[k] && f.params[k].name ? f.params[k].name : ("a" + k)));
    out.push("int64_t " + f.name + "(" + (ps.length ? ps.join(", ") : "void") + ");\n");
  }
  out.push("\n#endif /* " + guard + " */\n");
  irmod_free(mod);
  return out.join("");
}
function objc_strip_at(src) {
  /* elimina directivas @ de ObjC conservando el C de dentro.
     [CORRECCIÓN 2026-09-17, orden del arquitecto] Bug 20: el patrón
     [^;{]* cruzaba saltos de línea, así que '@implementation Foo' se comía
     la firma del primer método de debajo y hasta 'int main() {'. Ahora no
     cruza \n, y los métodos ObjC (- / + al inicio de línea) se quitan
     enteros: no son C válido. */
  return src
    .replace(/@(interface|implementation|end|property|synthesize|dynamic|class|protocol|optional|required|public|package|protected|private)\b[^;{\n]*[;{\n]?/g, " ")
    .replace(/@(selector|encode)\([^)]*\)/g, "0")
    .replace(/^[ \t]*[+-][ \t]*\([^)]*\)[^{;\n]*(\{[^}]*\})?[ \t]*$/gm, " ");
}
function cpp_frontend_compile_to_ir_native(ctx, src_path, log, io) {
  void ctx;
  const readFile = io ? io.readFile : null;
  const src = readFile ? readFile(src_path) : null;
  if (src === null || src === undefined) {
    log.add(ERR_FILE_NOT_FOUND, src_path, 0, 0,
            "No se encontró el archivo C++", "", "", "");
    return null;
  }
  return cpp_native_compile(src, src_path, log);
}


/* ===========================================================================
 * MÓDULO 27/24 — hgen NATIVO para Lua [CORRECCIÓN 2026-09-17, orden del arquitecto]
 * Antes: lua_frontend_generate_header requería RC.hgen_generate_for_file
 * inyectado → NULL. Ahora: generador nativo que parsea el .lua (con el
 * LUParser real) y emite un header C con los prototipos de las funciones
 * top-level. El hgen inyectado (si existe) conserva la prioridad.
 * ========================================================================= */
function lua_generate_header_native(src, src_path) {
  const ps = new LUParser(src, null, src_path);
  const mod = lu_parse_block(ps);   /* CHUNK con .list de statements */
  const lines = [];
  const guard = "RIGCOM_LUA_" + (src_path.replace(/[^A-Za-z0-9]/g, "_").toUpperCase());
  lines.push("/* Auto-generado por RIGCOMPILER_JS — hgen nativo Lua */\n");
  lines.push("/* Fuente: " + src_path + " */\n\n");
  lines.push("#ifndef " + guard + "\n#define " + guard + "\n\n");
  lines.push('#include "rigdeps/stdint.h"\n\n');
  let count = 0;
  const emit_fn = (name, fn) => {
    if (!name || !fn) return;
    let npar = 0;
    if (fn.b) {
      for (let i = 0; i < fn.b.n_list; i++) {
        const pm = fn.b.list[i];
        if (pm && pm.kind !== LUN.EX_DOTS) npar++;
      }
    }
    const ps_ = [];
    for (let i = 0; i < npar; i++) ps_.push("int64_t a" + i);
    lines.push("int64_t " + name + "(" + (ps_.length ? ps_.join(", ") : "void") + ");\n");
    count++;
  };
  if (mod) {
    for (let i = 0; i < mod.n_list; i++) {
      const s = mod.list[i];
      if (s && (s.kind === LUN.STMT_FUNC_DEF || s.kind === LUN.STMT_LOCAL_FUNC) && s.a)
        emit_fn(s.name, s.a);
    }
  }
  lines.push("\n#endif /* " + guard + " */\n");
  return { text: lines.join(""), n_funcs: count };
}

/* ===========================================================================
 * TANDA 6/6 — MÓDULO 10_ANDROID (14 archivos C → JS)
 *   rig_android_paths · rig_apk_sovereign_crypto · rig_apk_sovereign_manifest
 *   rig_binder_parcel · rig_binder_driver · rig_binder_svcmgr · rig_apk_sign
 *   jni_zero · rig_aar · rig_adb · rig_apk (bundle: absorbe apk_tool +
 *   apk_inspector + apkpack + repack_native — decisión bundle-vs-piezas:
 *   el bundle rig_apk.c es el canónico supersete; rig_apk_tool.c aporta
 *   rat_sign_android_sdk/rat_sign_sovereign que el bundle perdió al
 *   consolidar → se conservan ambas capacidades con el despachador del tool)
 *
 * Contrato IO inyectado (RC_ANDROID.io), fallo cerrado si falta:
 *   readFileBin(path)  → Uint8Array|null
 *   writeFileBin(path, u8) → bool
 *   stat(path)         → {size, isDir}|null
 *   readdir(dir)       → [names]|null       (sin "." ni "..")
 *   mkdirs(path)       → bool
 *   unlink(path)       → bool
 *   rename(a,b)        → bool
 *   popen(cmd)         → {out:string, code:number}|null
 *   which(name)        → bool
 *   urandom(n)         → Uint8Array|null
 *   deflateRaw(u8)     → Uint8Array|null   (opcional; sin ella → STORED,
 *                                           fiel al build RAT_HAVE_ZLIB=0)
 *   inflateRaw(u8, esperado) → Uint8Array|null (opcional, ídem)
 *   binder: open/ioctl/mmap/munmap/close  (módulo 32, opcional)
 *
 * DIVERGENCIAS AUTORIZADAS [DIVERGE-C]:
 *   · RatBN (limbs u32) y fp_t P-256 (limbs u32) → BigInt nativo de JS.
 *     Mismas matemáticas, sin desbordes; elimina de paso el bug documentado
 *     del C en rig_p256_sign (fp_mul mod p donde hacía falta mod n, parche
 *     con while-reduce) — aquí la reducción mod n es exacta.
 *   · mmap/fopen/popen/system → contrato io inyectado. Fallo cerrado.
 * ========================================================================= */

const RC_ANDROID = { io: null, broadcast: null };

function and_io() { return RC_ANDROID.io; }
