let adb_g_logcat_running = 0;
function adb_json_esc(s) {
  let out = "";
  s = String(s === null || s === undefined ? "" : s);
  for (let i = 0; i < s.length && out.length < 65536; i++) {
    const c = s.charCodeAt(i);
    if (s[i] === "\"") out += "\\\"";
    else if (s[i] === "\\") out += "\\\\";
    else if (c === 10) out += "\\n";
    else if (c === 13) out += "\\r";
    else if (c === 9) out += "\\t";
    else if (c >= 0x20) out += s[i];
  }
  return out;
}
function adb_run(subcmd, outsz) {
  outsz = outsz || 65536;
  const r = and_popen("adb " + subcmd + " 2>&1");
  if (!r) return { code: -1, out: "" };
  return { code: r.code, out: String(r.out || "").slice(0, outsz) };
}
function adb_detect() {
  const st = { available: false, adb_path: "", device_connected: false,
               device_serial: "", api_level: 0 };
  const candidates = [
    "adb",
    "/data/data/com.termux/files/usr/bin/adb",
    "/usr/bin/adb"
  ];
  const io = and_io();
  for (let i = 0; i < candidates.length; i++) {
    if (i === 0) {
      const r = and_popen("which adb 2>/dev/null");
      if (r && r.out) {
        const buf = String(r.out).split("\n")[0].replace(/[\r\n]+$/, "");
        if (buf) { st.adb_path = buf; st.available = true; break; }
      }
    } else if (io && typeof io.stat === "function") {
      const s = io.stat(candidates[i]);
      if (s && !s.isDir) { st.adb_path = candidates[i]; st.available = true; break; }
    }
  }
  if (!st.available) return st;
  const r = adb_run("devices");
  if (r.code !== 0) return st;
  for (const line of r.out.split("\n")) {
    if (line.includes("List of devices")) continue;
    if (line.includes("\tdevice")) {
      st.device_connected = true;
      const tab = line.indexOf("\t");
      if (tab > 0) st.device_serial = line.slice(0, tab);
      break;
    }
  }
  if (st.device_connected) {
    const api = adb_run("shell getprop ro.build.version.sdk");
    st.api_level = parseInt(String(api.out || "").trim(), 10) || 0;
  }
  return st;
}
function adb_emit_state(st) {
  if (!st) return;
  and_emit('{"ev":"adb_state","available":' + (st.available ? "true" : "false") +
           ',"device":' + (st.device_connected ? "true" : "false") +
           ',"serial":"' + adb_json_esc(st.device_serial) +
           '","adb_path":"' + adb_json_esc(st.adb_path) +
           '","api_level":' + (st.api_level | 0) + "}");
}
