    if (!tools.found_keytool) {
      rat_g_errbuf = "keytool no disponible y keystore '" + ks + "' no existe";
      return RAT_ERR_TOOLING;
    }
    const cmd = "keytool -genkey -v -keystore '" + ks + "' -alias '" + alias + "' " +
      "-keyalg RSA -keysize 2048 -validity 10000 " +
      "-storepass '" + pass + "' -keypass '" + pass + "' " +
      "-dname 'CN=RigCom,OU=RigadielForge,O=Urbina,C=CO' 2>&1";
    const g = and_popen(cmd);
