  if ((scheme === RAT_SIGN_V2 || scheme === RAT_SIGN_V1V2) && tools.found_apksigner) {
    const bin = (opt.apksigner && opt.apksigner[0]) ? opt.apksigner : "apksigner";
    const cmd = bin + " sign " +
      "--ks '" + ks + "' --ks-pass pass:'" + pass + "' " +
      "--ks-key-alias '" + alias + "' " +
      "--v1-signing-enabled " + (scheme === RAT_SIGN_V1V2 ? "true" : "false") + " " +
      "--v2-signing-enabled true " +
      "--out '" + apk_path + "' '" + apk_path + "' 2>&1";
    const r = and_popen(cmd);
    rc = r ? r.code : -1;
  } else if (tools.found_jarsigner) {
    const cmd = "jarsigner -verbose " +
      "-sigalg SHA256withRSA -digestalg SHA-256 " +
      "-keystore '" + ks + "' -storepass '" + pass + "' " +
      "'" + apk_path + "' '" + alias + "' 2>&1";
    const r = and_popen(cmd);
    rc = r ? r.code : -1;
  } else {
    rat_g_errbuf = "No hay herramienta de firma disponible (apksigner ni jarsigner)";
    return RAT_ERR_TOOLING;
  }
